fn bytes(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect()
}

fn integer(hex: &str) -> PaddedBigUint {
    let hex = format!("{}{hex}", "0".repeat(hex.len() % 2));
    let Ok(value) = PaddedBigUint::from_be(&bytes(&hex));
    value
}

/// BC 的 `FixedSecureRandom` 與 `DsaTestSecureRandom`：依序給出 `data`，之後全給零。
/// 零使 Miller-Rabin 的底數與 g 的 h 都是 2，同 BC 的 `DsaTestSecureRandom`。
struct Fixed {
    data: Vec<u8>,
    position: usize,
}

impl Fixed {
    fn new(hex: &str) -> Self {
        Self {
            data: bytes(hex),
            position: 0,
        }
    }

    fn next(&mut self) -> u8 {
        let byte = self.data.get(self.position).copied().unwrap_or(0);
        self.position += 1;
        byte
    }
}

impl TryRng for Fixed {
    type Error = Infallible;

    fn try_next_u32(&mut self) -> Result<u32, Infallible> {
        Ok(u32::from_le_bytes(core::array::from_fn(|_| self.next())))
    }

    fn try_next_u64(&mut self) -> Result<u64, Infallible> {
        Ok(u64::from_le_bytes(core::array::from_fn(|_| self.next())))
    }

    fn try_fill_bytes(&mut self, output: &mut [u8]) -> Result<(), Infallible> {
        output.iter_mut().for_each(|byte| *byte = self.next());
        Ok(())
    }
}

impl TryCryptoRng for Fixed {}

fn in_subgroup(params: &DsaParameters) -> bool {
    let p = NonZero::new(params.p().clone()).unwrap();
    params.g() > &PaddedBigUint::from(1u8)
        && params.g().mod_pow(params.q(), &p) == PaddedBigUint::from(1u8)
}

#[test]
fn fips_186_2_gives_the_p_q_and_counter_of_bouncy_castle() {
    let mut rng = Fixed::new(BASIC_K1);
    let mut generator = DsaParametersGenerator::new();
    generator.init_fips186_2(512, 80, &mut rng).unwrap();
    let params = generator.generate_parameters().unwrap();
    assert_eq!(params.p(), &integer(BASIC_P));
    assert_eq!(params.q(), &integer(BASIC_Q));
    let validation = params.validation().unwrap();
    assert_eq!(validation.counter(), 105);
    assert_eq!(validation.seed(), &bytes(BASIC_K1)[..]);
    assert!(in_subgroup(&params));
}

/// 以 seed 產生參數並和 BC 的 p、q、g、計數比對。
fn fips_186_3<D: tc_digest::Digest + core::fmt::Display>(
    digest: D,
    (seed, l, n, counter): (&str, u32, u32, u32),
    (p, q, g): (&str, &str, &str),
) -> DsaParameters {
    let mut rng = Fixed::new(seed);
    let mut generator = DsaParametersGenerator::with_digest(digest);
    generator
        .init_fips186_3(DsaParameterGenerationParams::new(l, n, 80, &mut rng))
        .unwrap();
    let params = generator.generate_parameters().unwrap();
    let validation = params.validation().unwrap();
    assert_eq!(validation.counter(), counter);
    assert_eq!(validation.seed(), &bytes(seed)[..]);
    assert_eq!(params.q(), &integer(q));
    assert_eq!(params.p(), &integer(p));
    assert_eq!(params.g(), &integer(g));
    params
}

#[test]
fn fips_186_3_with_1024_and_160_bits_matches_bouncy_castle() {
    fips_186_3(
        tc_sha::Sha1Digest::new(),
        (DSA2_1_SEED, DSA2_1_L, DSA2_1_N, DSA2_1_COUNTER),
        (DSA2_1_P, DSA2_1_Q, DSA2_1_G),
    );
}

#[test]
fn fips_186_3_with_2048_and_224_bits_matches_bouncy_castle() {
    fips_186_3(
        Sha224Digest::new(),
        (DSA2_2_SEED, DSA2_2_L, DSA2_2_N, DSA2_2_COUNTER),
        (DSA2_2_P, DSA2_2_Q, DSA2_2_G),
    );
}

