#[test]
fn key_generation_reads_x_as_bouncy_castle_does_and_y_is_g_to_the_x() {
    for (p, q, g, x, y) in [
        (DSA2_1_P, DSA2_1_Q, DSA2_1_G, DSA2_1_X, DSA2_1_Y),
        (DSA2_2_P, DSA2_2_Q, DSA2_2_G, DSA2_2_X, DSA2_2_Y),
        (DSA2_3_P, DSA2_3_Q, DSA2_3_G, DSA2_3_X, DSA2_3_Y),
        (DSA2_4_P, DSA2_4_Q, DSA2_4_G, DSA2_4_X, DSA2_4_Y),
    ] {
        let params = DsaParameters::new(integer(p), integer(q), integer(g));
        let mut rng = Fixed::new(x);
        let mut generator = DsaKeyPairGenerator::new();
        generator
            .init(DsaKeyGenerationParams::new(params, &mut rng))
            .unwrap();
        let (public_key, private_key) = generator.generate_key_pair().unwrap();
        assert_eq!(private_key.x(), &integer(x));
        assert_eq!(public_key.y(), &integer(y));
        assert_eq!(public_key.validate(), Ok(()));
        assert_eq!(private_key.validate(), Ok(()));
    }
}

#[test]
fn public_keys_outside_the_subgroup_or_range_are_refused() {
    let params = DsaParameters::new(integer(DSA2_1_P), integer(DSA2_1_Q), integer(DSA2_1_G));
    let p = integer(DSA2_1_P);
    for y in [
        PaddedBigUint::from(1u8),
        &p - 1u32,
        PaddedBigUint::from(2u8),
    ] {
        assert_eq!(
            DsaPublicKey::new(y, params.clone()).validate(),
            Err(DsaError::InvalidPublicKey)
        );
    }

    // BC 的 ModulusSizeBound：過大的模數在取冪之前就被擋下。
    let mut huge = tc_bigint::BigUint::from(0u8);
    huge.set_bit(20000, true);
    let huge = DsaParameters::new(
        PaddedBigUint::from(huge),
        PaddedBigUint::from(11u8),
        PaddedBigUint::from(2u8),
    );
    assert_eq!(
        DsaPublicKey::new(PaddedBigUint::from(2u8), huge).validate(),
        Err(DsaError::ModulusTooLarge)
    );
}

#[test]
fn errors_are_reported() {
    let mut generator = DsaParametersGenerator::new();
    assert_eq!(
        generator.generate_parameters(),
        Err(DsaError::NotInitialized)
    );
    let rng = &mut Fixed::new("");
    assert_eq!(
        DsaParametersGenerator::new().init_fips186_2(576 + 1, 80, rng),
        Err(DsaError::InvalidSize)
    );
    let rng = &mut Fixed::new("");
    assert_eq!(
        DsaParametersGenerator::new()
            .init_fips186_3(DsaParameterGenerationParams::new(2048, 160, 80, rng)),
        Err(DsaError::InvalidLengths)
    );
    let rng = &mut Fixed::new("");
    assert_eq!(
        DsaParametersGenerator::new()
            .init_fips186_3(DsaParameterGenerationParams::new(2048, 224, 80, rng)),
        Err(DsaError::UnsuitableDigest)
    );
    let rng = &mut Fixed::new("");
    assert_eq!(
        DsaParametersGenerator::with_digest(Sha256Digest::new()).init_fips186_2(1024, 80, rng),
        Err(DsaError::UnsuitableDigest)
    );
    let rng = &mut Fixed::new("");
    assert_eq!(
        DsaParametersGenerator::with_digest(Sha256Digest::new())
            .init_fips186_3(DsaParameterGenerationParams::new(2048, 256, 0, rng)),
        Err(DsaError::InvalidCertainty)
    );
}
